INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66972, 'spa', 'Cubierto de llagas', 'Estar cubierto de llagas o úlceras, padeciendo heridas supurantes. En Lucas 16:20, Lázaro es descrito como completamente ulcerado, yaciendo indefenso a la puerta del rico mientras los perros le lamían las llagas. El verbo pinta un cuadro vívido de su miseria y abandono, subrayando la insensibilidad del rico que ignoraba este sufrimiento a su puerta. La inversión de sus destinos en la eternidad convierte la parábola en una advertencia solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66973, 'spa', 'Arrastrar, jalar físicamente', 'Arrastrar, acarrear o tirar físicamente, con connotación de fuerza o compulsión. Pedro desenvaina su espada en Getsemaní (Juan 18:10), los discípulos arrastran la red a tierra (Juan 21:6, 11), y Pablo y Silas son arrastrados ante las autoridades (Hechos 16:19). El español emplea consistentemente ''arrastrar''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66974, 'spa', 'Atraer espiritualmente', 'Atraer a alguien en sentido espiritual o metafórico, usado exclusivamente de la acción divina que atrae personas hacia Cristo. En Juan 6:44 Jesús dice que nadie viene a él ''si el Padre no lo atrae'', y en Juan 12:32 promete ''atraer a todos'' hacia sí mismo. El español distingue este sentido con ''atraer''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66980, 'spa', 'Grecia o Hélade', 'Grecia o la Hélade, refiriéndose a la Grecia continental y al mundo helénico en general. En Hechos 20:2, los viajes de Pablo lo llevan a Grecia, donde permanece tres meses, probablemente en Corinto. La región representa el corazón intelectual y cultural del Mediterráneo, donde Pablo interactuó tanto con judíos como con griegos proclamando el evangelio, debatiendo con filósofos en Atenas y estableciendo iglesias en un entorno vibrante y moralmente complejo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66981, 'spa', 'Persona de identidad o cultura griega que, en el uso neotestamentario, ha pasado', 'Persona de identidad o cultura griega que, en el uso neotestamentario, ha pasado a representar a los gentiles en general: la mitad no judía de la humanidad en el binomio paulino ''judío y griego''. Pablo construye su soteriología universalista sobre este par: la salvación viene ''al judío primeramente y también al griego'' (Romanos 1:16; 2:9-10), y en Cristo la distinción queda abolida (Gálatas 3:28; Colosenses 3:11). En Hechos, los helenos son los gentiles temerosos de Dios que asisten a las sinagogas de la diáspora junto a los judíos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66990, 'spa', 'Idioma o contexto griego', 'Refiriéndose al idioma griego o contexto helénico, este sentido aparece en descripciones de griego escrito o hablado. Lucas 23:38 nota la inscripción trilingüe en la cruz de Jesús (hebreo, griego, latín), mientras que Apocalipsis 9:11 proporciona el nombre griego del ángel destructor. Ambas instancias enfatizan el griego como medio lingüístico de comunicación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66991, 'spa', 'Mujer griega o helenizada', 'Refiriéndose a mujeres de trasfondo griego o helenizado, este sentido enfatiza la identidad gentil en distinción de la judía. Marcos 7:26 lo usa para subrayar la barrera cultural que la mujer sirofenicia cruzó al buscar la ayuda de Jesús, mientras que Hechos 17:12 describe mujeres griegas prominentes que recibieron el evangelio en Berea. Ambos contextos destacan la inclusión gentil.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66992, 'spa', 'Judíos helenistas', 'Hechos 6:1 describe el conflicto en la iglesia primitiva: los helenistas se quejaron contra los hebreos porque sus viudas eran desatendidas en la distribución diaria. Hechos 9:29 relata a Pablo disputando con helenistas en Jerusalén, quienes buscaban matarlo. Hechos 11:20 menciona que algunos predicaron también a los helenistas, extendiendo el evangelio más allá de las fronteras lingüísticas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66993, 'spa', 'Lengua griega', 'Indicando comunicación en lengua griega, este adverbio aparece en contextos de inscripción multilingüe y discurso. Juan 19:20 enfatiza la accesibilidad trilingüe de la inscripción en la cruz, mientras que Hechos 21:37 muestra a Pablo demostrando su fluidez en griego para sorprender al comandante romano. Ambos casos destacan el griego como lengua franca del Mediterráneo oriental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66994, 'spa', 'Cargar a cuenta', 'Refiriéndose a acreditar o cargar algo a una cuenta, este sentido usa imágenes contables para cálculo moral y relacional. Romanos 5:13 discute el principio teológico de que el pecado no se imputa formalmente sin el estándar claro de la ley, mientras que Filemón 18 usa lenguaje comercial para la disposición de Pablo de asumir las deudas de Onésimo. Ambos enfatizan la atribución formal de responsabilidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66995, 'spa', 'Antepasado de Jesús', 'Antepasado de Jesús mencionado en Lucas 3:28, desconocido en los registros bíblicos e históricos. La genealogía de Lucas incluye muchos nombres así, resaltando las raíces profundas de Jesús en Israel y su plena participación en la historia humana. Cada generación olvidada importa en el plan redentor de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (66996, 'spa', 'esperar o aguardar', 'esperar o aguardar');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67006, 'spa', 'lo que se espera', 'lo que se espera');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67008, 'spa', 'poner la esperanza en, confiar en', 'poner la esperanza en, confiar en');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67015, 'spa', 'esperanza, expectativa', 'Expectativa confiada de un bien futuro, especialmente fundada en la promesa divina o la resurrección de Cristo. Central en la teología paulina como parte de la tríada permanente (1 Co 13:13) y ancla del alma (Heb 6:19). Aparece como contenido de la esperanza (''la esperanza de la gloria'', Col 1:27), como acto subjetivo de esperar (Ro 8:24: ''la esperanza que se ve no es esperanza'') y como base objetiva de la esperanza (Hch 23:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67016, 'spa', 'Mago opositor de Pablo', 'Elimas, también conocido como Bar-Jesús, mago judío que se opuso a Pablo en Chipre. En Hechos 13:8 intenta apartar al procónsul Sergio Paulo del evangelio. Pablo, lleno del Espíritu Santo, lo deja ciego, demostrando la superioridad del poder de Dios sobre la magia y provocando la conversión del procónsul.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67017, 'spa', 'Dios mío (vocativo)', 'Esta forma vocativa se dirige a Dios directamente en el grito de Jesús durante la crucifixión. Marcos 15:34 preserva las palabras arameas reales de Jesús antes de traducirlas, enfatizando la autenticidad de este momento angustioso. La repetición ''Eloí, Eloí'' intensifica la urgencia del clamor. Las transliteraciones en lenguas modernas intentan preservar el sonido del discurso original de Jesús.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67018, 'spa', 'mí mismo (pronombre reflexivo)', 'mí mismo (pronombre reflexivo)');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67026, 'spa', 'Subir o abordar un barco, embarcarse en una embarcacion', 'Subir o abordar un barco, embarcarse en una embarcacion. Cada aparicion en el NT involucra entrar en un barco para viajar por agua, tipicamente el Mar de Galilea. El verbo captura la accion fisica especifica de subir a bordo. Aparece en transiciones narrativas cuando Jesus se desplaza entre lugares de ministerio (Mt 8:23; 9:1; 13:2; 14:22; 15:39; Mc 4:1; 5:18; 6:45; 8:10, 13; Lc 5:3; 8:22, 37; Jn 6:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67035, 'spa', 'Arrojar dentro', 'Echar o lanzar dentro de un lugar, a menudo con fuerza o carácter definitivo. En Lucas 12:5, Jesús advierte sobre la autoridad de Dios para echar en la Gehena después de la muerte. El verbo destaca el juicio activo de consignar a alguien al castigo final, un poder que pertenece solo a Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67036, 'spa', 'Mojar comida', 'Refiriéndose a mojar alimento en un plato compartido, este sentido aparece en los relatos evangélicos de Jesús identificando a su traidor. Tanto Mateo 26:23 como Marcos 14:20 usan el acto de mojar juntos como la señal identificadora—no inusual en una comida, pero vuelto significativo por la palabra profética de Jesús. El detalle enfatiza la intimidad y la impactante traición de la comunión de mesa violada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67037, 'spa', 'Entrometerse o inmiscuirse', 'Entrar o inmiscuirse en algo, reclamando acceso indebido. En Colosenses 2:18 describe a falsos maestros que pretenden experiencias visionarias privilegiadas. Pablo critica este misticismo intrusivo como vanidad desconectada de Cristo. El verbo sugiere extralimitarse, irrumpir en ámbitos que exceden el lugar legítimo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67038, 'spa', 'Hacer embarcar', 'Poner a bordo de un barco, hacer embarcar a alguien. En Hechos 27:6, el centurión gestiona que Pablo y sus compañeros aborden un navío alejandrino con destino a Italia. El verbo capta el acto logístico de trasladar pasajeros a una embarcación, paso necesario en el dramático viaje de Pablo a Roma.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67039, 'spa', 'Mirar fijamente, contemplar con atención — mirar directa e intensamente a alguie', 'Mirar fijamente, contemplar con atención — mirar directa e intensamente a alguien, fijando los ojos con atención deliberada. Jesús ordena mirar las aves (Mt 6:26), contempla al joven rico con amor (Mr 10:21), mira a los discípulos declarando la posibilidad divina (Mt 19:26; Mr 10:27) y se vuelve para mirar a Pedro tras la negación (Lc 22:61). El Bautista mira fijamente a Jesús y proclama al Cordero (Jn 1:36, 42). El ciego sanado mira con claridad y queda restaurado (Mr 8:25).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67045, 'spa', 'Conmoción profunda', 'Conmoverse profundamente con emoción intensa —ya sea dolor, indignación o urgencia severa— expresada a veces como gemido o advertencia tajante. La palabra posee fuerza visceral: originalmente describía el resoplido de un caballo. Jesús «gime en espíritu» ante la tumba de Lázaro (Jn 11:33, 38), movido por el dolor y quizá la indignación ante la muerte. En Mateo 9:30 y Marcos 1:43 «advierte severamente» a los sanados que guarden silencio, con tono apremiante y casi imperioso.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67046, 'spa', 'Vomitar por rechazo', 'Vomitar o arrojar de la boca, expresando asco o rechazo total. En Apocalipsis 3:16, Jesús advierte a los tibios laodicenses que los vomitará de su boca. La metáfora es visceral e impactante, equiparando su estado espiritual con algo nauseabundo e intolerable. Ni calientes ni fríos, provocan repulsión. La imagen urge al arrepentimiento inmediato.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67047, 'spa', 'Enfurecerse con locura', 'Estar enfurecido o enloquecido de ira, impulsado por rabia intensa contra alguien. En Hechos 26:11, Pablo describe cómo perseguía a los cristianos hasta ciudades extranjeras, poseído por un fanatismo irracional. El verbo transmite una furia sin límites. Su testimonio de tal locura magnifica la gracia transformadora de Cristo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67048, 'spa', 'Dios con nosotros', 'Emanuel, «Dios con nosotros», título mesiánico de Isaías 7:14 aplicado a Jesús en Mateo 1:23. Expresa el corazón teológico de la encarnación: Dios habita con su pueblo. En el niño nacido de virgen, la presencia divina se establece en la historia. Es confesión de fe que reconoce a Jesús como cumplimiento de la esperanza de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67049, 'spa', 'Aldea cerca de Jerusalén', 'Aldea a unos once kilómetros de Jerusalén, destino de dos discípulos el día de la resurrección. En Lucas 24:13, caminan hacia Emaús acompañados por Jesús resucitado sin reconocerlo, mientras Él les abre las Escrituras. Al partir el pan lo reconocen. Emaús es lugar de revelación donde el dolor se vuelve gozo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67050, 'spa', 'Permanecer firme en', 'Permanecer con firmeza en algo, perseverar dentro de un compromiso, lugar o pacto. El prefijo ἐν- localiza la permanencia: se permanece dentro de la fe (Hch 14:22), dentro de una morada (Hch 28:30) o dentro de los términos de un pacto (He 8:9, citando Jer 31:32). Gá 3:10 advierte sobre permanecer en todo lo escrito en la ley.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67051, 'spa', 'Príncipe heveo de Siquem', 'Hamor, príncipe heveo de Siquem que vendió tierra a Abraham según Génesis 33:19. En Hechos 7:16, Esteban referencia esta transacción en su recorrido histórico. La mención evoca el período patriarcal cuando se adquirieron propiedades en la Tierra Prometida. La referencia ancla la historia de Jesús en la larga historia de Israel.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67052, 'spa', 'mi (posesivo atributivo)', 'Posesivo atributivo ''mi'', que modifica un sustantivo para expresar pertenencia o relación en primera persona. Jesús lo emplea repetidamente en el Evangelio de Juan para afirmar un vínculo personal único: ''mis mandamientos'' (Jn 14:15), ''mi gozo'' (Jn 15:11), ''mi Padre'' (Mt 20:23). En español se traduce directamente como mi.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67055, 'spa', 'mío (posesivo sustantivo)', 'Posesivo sustantivo ''mío'' o ''lo mío'', usado sin sustantivo acompañante para denotar las posesiones, personas o ámbito de uno. En Mt 20:15: ''¿No me es lícito hacer lo que quiero con lo mío (τοῖς ἐμοῖς)?''; en Jn 10:14, Jesús dice ''conozco a los míos (τὰ ἐμά) y los míos me conocen''. El español mío distingue claramente este uso del atributivo mi.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67064, 'spa', 'Burla despectiva', 'Describiendo burlas despectivas dirigidas a los fieles, este sentido aparece en contextos de sufrimiento y prueba escatológica. Hebreos 11:36 incluye las burlas en un catálogo de persecuciones soportadas por los santos del Antiguo Testamento, mientras que 2 Pedro 3:3 advierte de burladores de los últimos días que se mofan de la promesa del regreso de Cristo. Ambos enfatizan el escarnio como forma de hostilidad contra el pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67065, 'spa', 'burlarse, ridiculizar, escarnecer — Burlarse, ridiculizar, escarnecer o tratar c', 'burlarse, ridiculizar, escarnecer — Burlarse, ridiculizar, escarnecer o tratar con desprecio mediante palabras y acciones. Este sentido domina el uso neotestamentario, concentrado en las predicciones y los relatos de la Pasión: los soldados se burlan de Jesús antes de la crucifixión (Mt 27:29, 31; Mc 15:20; Lc 22:63) y los presentes al pie de la cruz lo escarnecen (Mt 27:41; Mc 15:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67071, 'spa', 'engañar, embaucar — Engañar, embaucar o dejar en ridículo a alguien, con énfasis', 'engañar, embaucar — Engañar, embaucar o dejar en ridículo a alguien, con énfasis en la astucia más que en la burla verbal. En Mateo 2:16, Herodes percibe que los magos lo han ''burlado'', no riéndose de él, sino evadiendo su trampa y partiendo por otro camino. El contexto narrativo deja claro que se trata de un engaño: Herodes ha sido superado en estrategia, no simplemente objeto de mofa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67075, 'spa', 'Burlador, escarnecedor', 'Burlador o escarnecedor que ridiculiza la verdad religiosa, particularmente la esperanza escatológica. Ambas apariciones en el NT (2 Pe 3:3, Jud 18) describen escépticos de los últimos tiempos que se burlan de la promesa del regreso de Cristo mientras siguen sus propios deseos. La consistencia translingüística (inglés ''mockers'', español ''burladores'', francés ''moqueurs'', alemán ''Spötter'') refleja la naturaleza activa y despreciativa de su burla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67076, 'spa', 'Habitar y caminar entre', 'Caminar o habitar entre personas, indicando presencia activa y comunión dentro de una comunidad. En 2 Corintios 6:16, Pablo cita la promesa de Dios de caminar entre su pueblo como su Dios. El verbo transmite no una residencia estática sino una presencia dinámica: Dios moviéndose entre los suyos, involucrado en sus vidas. Para la iglesia, esto significa que el Espíritu Santo habita activamente en la comunidad creyente, haciéndola templo vivo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67077, 'spa', 'Llenar o saciar', 'Llenar completamente o satisfacer en abundancia, generalmente con alimento, provisión o gozo. Lucas 1:53 celebra que Dios llena a los hambrientos; Lucas 6:25 advierte a los saciados que vendrá el hambre. Juan 6:12 emplea el participio perfecto para la multitud plenamente satisfecha tras la alimentación milagrosa. Hechos 14:17 amplía el sentido a la provisión divina que llena los corazones de sustento y alegría, mientras Romanos 15:24 lo aplica al deseo de gozar de la compañía fraternal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67078, 'spa', 'Caer en, caer entre', 'Caer dentro de un lugar, hoyo, trampa o situación perjudicial, implicando siempre la entrada en una condición indeseable, ya sea física o espiritual. El sentido literal aparece en Mateo 12:11 (una oveja que cae en un hoyo) y Lucas 6:39 (caer en un foso), mientras que Lucas 10:36 narra al viajero que cayó entre ladrones. Las Epístolas Pastorales emplean el término metafóricamente para el peligro espiritual: un anciano novato puede caer en la condenación y en el lazo del diablo (1 Timoteo 3:6-7).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67084, 'spa', 'Enredarse, quedar atrapado', 'Enredarse, enmarañarse o quedar atrapado en algo que restringe o ata. En 2 Ti 2:4, Pablo lo usa respecto a un soldado que evita enredarse en asuntos civiles para agradar a su comandante. En 2 Pe 2:20, describe ser vencido nuevamente por las contaminaciones de las que se había escapado. El trasfondo léxico remite al tejido o entrelazado, sugiriendo un enmarañamiento completo. Las traducciones translingüísticas enfatizan la restricción de la libertad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67085, 'spa', 'Trenzado del cabello', 'El trenzado o entrelazado del cabello en estilos ornamentales. En 1 Pedro 3:3, Pedro advierte contra permitir que el adorno exterior —peinados elaborados, joyas de oro, ropa fina— defina la belleza de una mujer. No prohíbe tales cosas, sino que exhorta a priorizar: la belleza imperecedera de un espíritu manso y humilde supera con creces el arreglo costoso. El sustantivo simboliza la tentación de invertir en la apariencia externa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67086, 'spa', 'Respirar o exhalar', 'Respirar o exhalar, frecuentemente de manera metafórica describiendo la actitud o disposición dominante de una persona. En Hechos 9:1, Saulo respira amenazas y muerte contra los discípulos; todo su ser exhala hostilidad hacia los cristianos. La imagen es poderosa: la persecución no es un acto ocasional sino el aire mismo que respira, su pasión consumidora. Esto hace su conversión aún más dramática.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67087, 'spa', 'Comerciar, explotar', 'Dedicarse al comercio o negocio; comprar y vender con fines de lucro. En Stg 4:13, describe actividad comercial planificada (''negociaremos/haremos negocios''), mientras que en 2 Pe 2:3 lleva el sentido negativo de explotación (''harán mercadería de vosotros/os explotarán''). El trasfondo léxico enfatiza viajar con propósitos comerciales. El español alterna entre ''negociar'' neutral y contextos explotadores, reflejando la tensión semántica.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67088, 'spa', 'Comercio o negocio', 'Comercio, negocio o actividad mercantil, especialmente empresa de carácter comercial. En Mateo 22:5, representa las preocupaciones mundanas que llevan a las personas a ignorar la invitación del rey a la fiesta de bodas. Uno va a su campo, otro a su negocio: ambas ocupaciones legítimas que sin embargo se convierten en excusas para rechazar el llamado. El sustantivo simboliza cómo las preocupaciones terrenales, por respetables que sean, pueden cegarnos ante lo eterno.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67089, 'spa', 'Mercado o plaza comercial', 'La única aparición en el Nuevo Testamento, en Juan 2:16, recoge la reprensión de Jesús durante la purificación del templo: "No hagáis de la casa de mi Padre casa de mercado." Las glosas interlingüísticas apuntan consistentemente a la actividad comercial. El uso clásico muestra que ἐμπόριον designaba centros de intercambio y estaciones comerciales donde los mercaderes realizaban sus negocios, particularmente en Corinto y Atenas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67090, 'spa', 'Mercader o comerciante', 'Comerciante viajero o mayorista que importa y vende mercancías, a menudo por mar. En Mt 13:45 el mercader que busca perlas hermosas representa a quien reconoce un valor supremo y lo sacrifica todo por obtenerlo. En Ap 18:3, 11, 15, 23, los mercaderes de la tierra se enredan en el comercio opulento de Babilonia y lloran cuando este colapsa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67091, 'spa', 'Incendiar por juicio', 'En Mateo 22:7, la respuesta airada del rey ante el rechazo de su invitación incluye incendiar la ciudad de los homicidas. Es vocabulario de juicio que describe destrucción total. Las traducciones multilingües (incendió, brûler) captan la naturaleza violenta de la acción. El uso clásico para quemar ciudades concuerda con el contexto parabólico de juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67092, 'spa', 'delante de, ante', 'Preposición o adverbio que indica posición espacial delante de algo, movimiento direccional por delante de alguien, o relación de presencia ante la mirada de otro. Espacial: la estrella que iba ''delante de'' los magos (Mt 2:9), echar perlas ''delante de'' los cerdos (Mt 7:6). Relacional-presentacional: hacer buenas obras ''delante de los hombres'' (Mt 5:16), confesar o negar ''delante de mi Padre'' (Mt 10:32-33). También porta un sentido de prioridad de rango y tiempo (Jn 1:15, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67096, 'spa', 'Escupir a alguien', 'Escupir sobre alguien como acto deliberado de desprecio, burla o maltrato físico. Las seis apariciones en el NT se concentran en los relatos de la Pasión y en las predicciones de Jesús al respecto. En el juicio ante el Sanedrín, los miembros del concilio escupen en el rostro de Jesús (Mateo 26:67; Marcos 14:65). Los soldados romanos repiten la afrenta durante la flagelación y la burla (Mateo 27:30; Marcos 15:19). Jesús mismo anuncia este trato en Marcos 10:34.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67102, 'spa', 'Visible, manifiesto', 'Visible, manifiesto, mostrado abiertamente a la vista. En Hch 10:40, Dios concedió que Jesús se hiciera manifiesto a testigos escogidos después de su resurrección—no a todos, sino a los designados para verlo corporalmente. En Ro 10:20, la profecía de Isaías describe a Dios haciéndose manifiesto a quienes no lo buscaban. El sentido clásico de aparecer corporalmente o ser presentado abiertamente en tribunal subyace ambos usos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67103, 'spa', 'Informar, denunciar, dar a conocer — designa el acto formal de informar, declara', 'Informar, denunciar, dar a conocer — designa el acto formal de informar, declarar o presentar información ante una autoridad. Las cinco apariciones neotestamentarias se concentran en Hechos 23-25, donde describe la presentación de cargos o informes ante comandantes y gobernadores romanos. La evidencia multilingüe es consistente: ''informaron/informaste'' en español, ''présenter'' en francés, apuntando a un registro oficial y jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67104, 'spa', 'Revelar, manifestar, aparecer — describe hacer algo visible, manifiesto o patent', 'Revelar, manifestar, aparecer — describe hacer algo visible, manifiesto o patente, ya sea mediante una autorrevelación activa o una aparición pasiva. Jesús lo usa para su prometida automanifestación a los discípulos fieles (Jn 14:21-22), Mateo lo emplea para la sorprendente aparición de santos resucitados en Jerusalén tras la crucifixión (Mt 27:53), y Hebreos lo aplica tanto a Cristo presentándose ante Dios (Heb 9:24) como a la revelación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67111, 'spa', 'Aterrorizado por lo divino', 'En estado de terror o alarma, generalmente provocado por una manifestación divina o sobrenatural. Lc 24:5 y 24:37 describen el miedo ante apariciones de la resurrección. Hch 10:4 capta el espanto de Cornelio al ver un ángel, y Hch 24:25 extiende el término al sobresalto de Félix ante la predicación de Pablo sobre la justicia y el juicio venidero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67112, 'spa', 'Soplar el Espíritu', 'Juan 20:22 registra al Cristo resucitado soplando sobre los discípulos y ordenándoles recibir el Espíritu Santo. Este gesto pneumático evoca Génesis 2:7, donde Dios sopló aliento de vida en Adán. Las glosas multilingües (sopló, souffler, anhauchen) subrayan el acto físico, mientras que su significado teológico es pneumatológico: Jesús imparte el Espíritu mediante su aliento, un acto creador y vivificante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67113, 'spa', 'Implantado interiormente', 'Santiago 1:21 exhorta a recibir con mansedumbre ''la palabra implantada'' capaz de salvar las almas. Es lenguaje agrícola: la palabra de Dios no solo se oye externamente, sino que se planta y echa raíces en el corazón receptivo. Los textos clásicos muestran que ἔμφυτος podía significar innato o deliberadamente plantado. Santiago favorece lo segundo: verdad divina sembrada en el creyente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67114, 'spa', 'en/dentro de (locativo)', 'Ubicación física dentro de un lugar, espacio o contenedor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67115, 'spa', 'entre/comunal', 'En medio de un grupo; dentro de una comunidad o colectivo de personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67116, 'spa', 'por/instrumental', 'Indica el medio, instrumento o manera por la cual se realiza algo; por medio de, mediante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67117, 'spa', 'en/temporal', 'Durante un período de tiempo; en el transcurso de, mientras.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67121, 'spa', 'en/esfera', 'Dentro del ámbito, esfera o dominio de algo; en el contexto de, en relación con.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67126, 'spa', 'Tomar en brazos', 'Tomar en los brazos, abrazar. Ambas apariciones muestran a Jesús tomando niños en sus brazos: en Mr 9:36 mientras enseñaba sobre humildad y recibir el reino, y en Mr 10:16 mientras bendecía a niños traídos a él. La voz media sugiere acción personal y deliberada. El español preserva la forma participial (''habiéndolo abrazado''), enfatizando la acción completada de tomar en brazos. El gesto expresa calidez y aceptación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67127, 'spa', 'Criatura marina', 'Santiago 3:7 cataloga los logros humanos en domesticación: bestias, aves, serpientes y ''criaturas del mar''. El genitivo plural ἐναλίων designa seres marinos. La evidencia multilingüe (marinos, im Meer lebend) confirma la referencia acuática. Los textos clásicos usaban este término para peces y dioses marinos. Santiago argumenta que, habiendo subyugado toda la creación, la lengua permanece indómita.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67128, 'spa', 'En presencia de', 'En la presencia de, delante de (con genitivo). En Lucas 1:8, Zacarías desempeña servicio sacerdotal delante de Dios (ἔναντι τοῦ θεοῦ). En Hechos 8:21, Pedro le dice a Simón que su corazón no es recto delante de Dios. El trasfondo léxico en la LXX y el griego posterior enfatiza estar en la presencia o vista de alguien. Las traducciones preservan el sentido formal y posicional: español ''delante'', francés ''devant'', sugiriendo estar de pie ante alguien.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67129, 'spa', 'En presencia de', 'En la presencia de, ante el rostro de, o a la vista de, típicamente Dios, un gobernante o una asamblea. Lc 1:6 describe a Zacarías e Isabel como justos ''delante de Dios''. Lc 24:19 alaba a Jesús como poderoso ''delante de Dios y de todo el pueblo''. Hch 7:10 relata cómo José halló gracia ''delante de Faraón''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67130, 'spa', 'Contrario, opuesto', 'Contrario, que se opone o es hostil — actuando contra alguien en dirección, propósito o actitud. Se usa del viento que sopla contra la barca (Mateo 14:24; Marcos 6:48), de vientos adversos en la navegación (Hechos 27:4), y de la oposición de Pablo al nombre de Jesús (Hechos 26:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67132, 'spa', 'Enfrente, posición espacial', 'Situado físicamente enfrente o de cara a alguien, relación espacial sin connotación hostil. En Marcos 15:39, el centurión que estaba ''enfrente'' (ἐξ ἐναντίας) de Jesús lo vio exhalar el último aliento y lo confesó como Hijo de Dios. El español ''enfrente'' en lugar de ''contrario'', y el marco puramente posicional de la narración, confirman un sentido espacial-locativo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67137, 'spa', 'Comenzar, iniciar', 'Comenzar, hacer un comienzo, iniciar. En Gál 3:3, Pablo pregunta si comenzaron por el Espíritu solo para completar por la carne, una pregunta retórica que resalta la inconsistencia. En Fil 1:6, Pablo expresa confianza en que Dios quien comenzó la buena obra la completará. Los participios aoristos marcan el punto de partida decisivo. El trasfondo clásico incluye comenzar ritos sacrificiales y asumir un cargo. Las traducciones en varios idiomas preservan el énfasis en el acto inicial de empezar algo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67138, 'spa', 'Necesitado materialmente', 'Hechos 4:34 celebra el milagro económico de la iglesia primitiva: ''No había ningún necesitado entre ellos''. Esto evoca Deuteronomio 15:4 sobre la ausencia de pobres en Israel. El adjetivo ἐνδεής señala carencia material, y su negación indica provisión completa. Las glosas como necesitado y manquant captan la dimensión económica. La práctica comunitaria erradicó la necesidad, poderoso testimonio del evangelio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67139, 'spa', 'Evidencia del juicio divino', 'En 2 Tesalonicenses 1:5, la persecución se convierte en ἔνδειγμα —evidencia clara— del justo juicio de Dios. La perseverancia de los creyentes bajo la prueba demuestra que son dignos del reino de Dios, mientras sus opresores enfrentan juicio futuro. Esta lógica paradójica convierte el sufrimiento presente en señal de vindicación futura. Los glosas multilingües (evidencia, prueba, proof, Beweis) apuntan todas a una fuerza demostrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67140, 'spa', 'Mostrar, demostrar, exhibir — poner de manifiesto, demostrar o exhibir públicame', 'Mostrar, demostrar, exhibir — poner de manifiesto, demostrar o exhibir públicamente, haciendo evidente ante otros una cualidad, actitud o realidad. De Dios: demostrando su ira contra Faraón para dar a conocer su poder (Ro 9:17, 22), mostrando las sobreabundantes riquezas de la gracia en Cristo (Ef 2:7) y exhibiendo su perfecta paciencia mediante la conversión de Pablo (1 Ti 1:16). De las personas: mostrando la obra de la ley inscrita en el corazón (Ro 2:15), demostrando amor y fidelidad (2 Co 8:24; Heb 6:10-11) y exhibiendo buena conducta (Tit 2:10; 3:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67149, 'spa', 'Demostración pública', 'Demostración pública o prueba visible que establece una verdad ante testigos. Las cuatro apariciones neotestamentarias enfatizan evidencia verificable externamente. En Ro 3:25-26, Dios presenta a Cristo como demostración (ἔνδειξιν) de la justicia divina, repetido dos veces para dar énfasis. En 2 Co 8:24, los corintios deben exhibir prueba (ἔνδειξιν) de su amor. Fil 1:28 trata la audacia de los adversarios como evidencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67150, 'spa', 'Once, los Once', 'El número cardinal once, usado en cada una de sus apariciones neotestamentarias como cuasi-título para el grupo apostólico tras la defección de Judas Iscariote y antes de la elección de Matías. ''Los Once'' (οἱ ἕνδεκα) aparece en la Gran Comisión (Mateo 28:16), la aparición postresurreccional (Marcos 16:14), el informe desde el sepulcro vacío (Lucas 24:9), el regreso de los discípulos de Emaús (Lucas 24:33) y la elección de Matías (Hechos 1:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67151, 'spa', 'Ordinal undécimo', 'Mateo 20:6 y 20:9 hacen referencia al clímax de la parábola: los obreros contratados a la undécima hora recibieron el mismo pago completo, ilustrando la economía de la gracia. Apocalipsis 21:20 enumera los fundamentos de la ciudad celestial, donde la undécima piedra ocupa su lugar en el esplendor ordenado de la nueva creación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67152, 'spa', 'Posibilidad e inevitabilidad', 'Lucas 13:33 contiene la amarga observación de Jesús: «No es posible que un profeta perezca fuera de Jerusalén». Se trata de una ironía dramática: la ciudad santa asesina a los portavoces de Dios. El verbo ἐνδέχεται expresa no solo mera posibilidad, sino un patrón histórico y una inevitabilidad profética. Jesús camina a sabiendas hacia Jerusalén y hacia la cruz.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67153, 'spa', 'Morar en casa', 'Las tres apariciones se concentran en 2 Corintios 5:6-9, junto con ἐκδημέω. Pablo contrasta estar en casa en el cuerpo (lejos del Señor) con estar fuera del cuerpo (en casa con el Señor), y concluye que tanto presentes como ausentes, el objetivo es agradar a Cristo. La metáfora establece la vida terrenal como residencia provisional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67154, 'spa', 'Vestir, ataviarse', 'Vestir, ataviarse, poner vestiduras. En Marcos 15:17, los soldados visten a Jesús de púrpura como burla antes de la crucifixión. En Lucas 16:19, el rico se vestía habitualmente de púrpura y lino fino (tiempo imperfecto mostrando acción repetida). La entrada léxica nota el uso medio para vestirse a uno mismo. El alemán y el español preservan la distinción entre vestir a otros y vestirse a sí mismo. El acto es moralmente neutral; el contexto determina su significado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67155, 'spa', 'Justo, merecido', 'Justo, correcto, conforme a la justicia; merecido, legítimo. En Rom 3:8, Pablo considera hipotéticamente que la condenación podría ser justa (δίκαιον) si el cargo fuera cierto, aunque rechaza la premisa. En Heb 2:2, cada transgresión recibió justa retribución (ἔνδικον μισθαποδοσίαν), enfatizando la retribución merecida. El uso clásico incluye contextos legales (reclamos legítimos, días de tribunal) y contextos morales de lo que es justo y apropiado según normas de justicia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67156, 'spa', 'Construcción arquitectónica', 'Apocalipsis 21:18 describe la ἐνδόμησις del muro como jaspe puro. Este término arquitectónico denota la construcción o composición estructural de la muralla. Las glosas multilingües (structure, estructura, Bauwerk) enfatizan la forma edificada. En el uso clásico incluía rompeolas y estructuras moldeadas. La visión de Juan transforma la arquitectura terrenal en simbolismo trascendente, donde los materiales de construcción revelan la gloria divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67157, 'spa', 'Ser glorificado', 'Ser glorificado, recibir gloria, ser hecho glorioso (pasivo). Ambas apariciones en 2 Tesalonicenses 1 (vv. 10, 12) describen a Cristo siendo glorificado en sus santos y la glorificación mutua de Cristo y los creyentes. Pablo ora para que el nombre del Señor Jesús sea glorificado en ellos y ellos en él. La voz pasiva enfatiza la acción divina en lugar de la autoglorificación. El trasfondo septuagintal se conecta con la manifestación de la gloria divina en contextos de adoración.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67158, 'spa', 'Glorioso u honrado', 'Glorioso, espléndido o tenido en alta honra, describiendo personas distinguidas o cosas de calidad notable. La raíz en δόξα (''gloria, reputación'') fundamenta cada uso. Lucas 7:25 lo aplica a vestiduras espléndidas; Lucas 13:17 a las obras admirables de Jesús; Efesios 5:27 a la perfección escatológica de la iglesia. El uso paulino en 1 Corintios 4:10 es amargamente irónico: ''vosotros sois ἔνδοξοι, pero nosotros somos deshonrados''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67159, 'spa', 'Vestido, vestimenta', 'Prenda exterior o artículo de vestir. Se usa de la vestidura de Juan el Bautista (Mateo 3:4), la ropa del invitado a la boda (Mateo 22:11-12), el vestido resplandeciente del ángel (Mateo 28:3), y la enseñanza de Jesús sobre no preocuparse por el vestido (Mateo 6:25, 28). En Mateo 7:15 se extiende metafóricamente al engaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67161, 'spa', 'Fortalecer, capacitar', 'Fortalecer, capacitar: uso activo o transitivo en el que Dios o Cristo es el agente que dota a una persona de poder para el ministerio, la resistencia o la misión. Tres pasajes son explícitamente cristológicos: el testimonio agradecido de Pablo de que Cristo Jesús ''me fortaleció'' para el servicio apostólico (1 Ti 1:12), el icónico ''todo lo puedo en aquel que me fortalece'' (Fil 4:13), y ''el Señor estuvo a mi lado y me dio fuerzas'' (2 Ti 4:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67163, 'spa', 'Ser fortalecido, crecer', 'Ser fortalecido, crecer en vigor: uso pasivo o intransitivo que describe al receptor que está siendo capacitado o que aumenta en poder. Saulo ''se fortalecía cada vez más'' en su predicación tras Damasco (Hch 9:22), Abraham ''fue fortalecido en la fe, dando gloria a Dios'' sin vacilar ante la promesa (Ro 4:20), y los imperativos paulinos urgen a los creyentes a ser fortalecidos en el Señor (Ef 6:10; 2 Ti 2:1).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67168, 'spa', 'Infiltración furtiva', '2 Timoteo 3:6 advierte contra quienes «se introducen en las casas» y cautivan a mujeres débiles. El participio presente ἐνδύνοντες sugiere un comportamiento furtivo habitual y continuo. Se trata de una conducta depredadora disfrazada de piedad. El uso clásico de ponerse ropa se extiende metafóricamente aquí al acto de adoptar una falsa apariencia para ganar acceso y manipular.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67169, 'spa', 'Acto de vestirse', 'En 1 Pedro 3:3, se enseña a las esposas que su adorno no sea meramente la ἔνδυσις externa de vestiduras. La construcción genitiva vincula el acto de vestirse con la indumentaria, enfatizando el vestirse como forma de decoración. Las glosas multilingües (wearing, vestirse, Bekleidung) apuntan al proceso de vestimenta. Pedro establece un contraste claro: en lugar de elaborados adornos exteriores, buscar la belleza imperecedera del espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67170, 'spa', 'Estar vestido o haber sido vestido, la condición pasiva o estativa de llevar alg', 'Estar vestido o haber sido vestido, la condición pasiva o estativa de llevar algo puesto. Siete ocurrencias enfatizan el estado resultante más que el acto: el invitado a la boda sin vestidura adecuada (Mateo 22:11), Juan el Bautista vestido de pelo de camello (Marcos 1:6), y los santos resucitados ''vestidos de ropas blancas'' (Apocalipsis 1:13). El español vestido marca este estado completado y permanente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67171, 'spa', 'Ponerse o vestirse, el sentido activo/medio de vestirse con ropas, armadura o cu', 'Ponerse o vestirse, el sentido activo/medio de vestirse con ropas, armadura o cualidades figuradas. Dominante con 18 ocurrencias, abarca tanto el vestirse literal (Marcos 6:9, ''no os pongáis dos túnicas'') como la investidura metafórica (''vestíos del Señor Jesucristo'', Romanos 13:14; ''vestíos del nuevo hombre'', Efesios 4:24). El español vestíos capta naturalmente la voz media reflexiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67173, 'spa', 'Vestir a otra persona, el uso causativo-transitivo donde el sujeto viste a otro', 'Vestir a otra persona, el uso causativo-transitivo donde el sujeto viste a otro. Solo 3 ocurrencias, pero narrativamente vívidas: los soldados desnudan y vuelven a vestir a Jesús en la crucifixión (Mateo 27:31; Marcos 15:20), y el padre ordena ''ponedle el mejor vestido'' al hijo pródigo que regresa (Lucas 15:22). El español vestidlo hace inequívoca la acción dirigida a otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67189, 'spa', 'Envolver para sepultura', 'Marcos 15:46 registra el acto devoto de José de Arimatea: tras bajar el cuerpo de Jesús, ''lo envolvió en la sábana.'' El verbo ἐνείλησεν describe la acción de amortajar conforme a la costumbre funeraria judía. José arriesga su propia reputación al asociarse con un condenado para dar a Jesús una sepultura digna y honrosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67190, 'spa', 'Lo que está dentro', 'Lucas 11:41 contiene la corrección de Jesús al externalismo farisaico: ''Dad limosna de lo que está dentro.'' El participio neutro plural τὰ ἐνόντα designa contenidos o posesiones disponibles. El contraste es entre el lavamiento exterior (v. 39) y la generosidad interior. Jesús redirige la atención de la superficie ritual hacia la disposición genuina del corazón.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67191, 'spa', 'Preposición causal que significa ''a causa de, por causa de, por amor de'', expres', 'Preposición causal que significa ''a causa de, por causa de, por amor de'', expresando la razón motivadora o el propósito último detrás de una acción. En el NT marca de forma abrumadora el costo del discipulado: bienaventuranzas para los perseguidos ''por mi causa'' (Mateo 5:10-11), la paradoja de perder y hallar la vida ''por mi causa'' (Mateo 10:39; 16:25; Marcos 8:35), y las pruebas ante autoridades ''por mi nombre'' (Mateo 10:18; Marcos 13:9; Lucas 21:12). Pablo se hace eco: ''por causa de ti nos matan todo el día'' (Romanos 8:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67198, 'spa', 'Poder operante divino', 'Poder activo y operante o energía en acción — especialmente energía divina que produce efectos tangibles. En Pablo designa la operación que resucitó a Cristo (Efesios 1:19), la energía para el ministerio apostólico (Efesios 3:7; Colosenses 1:29), el poder de Cristo para sujetar todas las cosas (Filipenses 3:21), y la fuerza que hace crecer el cuerpo (Efesios 4:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67199, 'spa', 'Obrar, estar activo u operar — usado intransitivamente de Dios, fuerzas espiritu', 'Obrar, estar activo u operar — usado intransitivamente de Dios, fuerzas espirituales o poderes que producen actividad. Herodes piensa que los poderes de Juan el Bautista ''están obrando'' en Jesús (Mateo 14:2; Marcos 6:14). Pablo lo usa teológicamente: las pasiones pecaminosas obraban en nuestros miembros (Romanos 7:5), Dios obra todas las cosas en todos (1 Corintios 12:6), y el Espíritu distribuye dones según opera (1 Corintios 12:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67203, 'spa', 'Ser eficaz, producir resultados — enfatizando no meramente la actividad sino el ', 'Ser eficaz, producir resultados — enfatizando no meramente la actividad sino el resultado potente. La fe ''obra por el amor'' (Gálatas 5:6), la palabra de Dios ''obra eficazmente'' en los creyentes (1 Tesalonicenses 2:13), Pablo trabaja conforme al poder de Dios ''que obra poderosamente'' en él (Colosenses 1:29), y Santiago declara que la oración del justo ''es poderosa y eficaz'' (Santiago 5:16).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67212, 'spa', 'Activamente eficaz', 'En 1 Corintios 16:9 Pablo describe una puerta abierta para una obra eficaz a pesar de muchos adversarios. Filemón 6 expresa la oración de que la fe compartida llegue a ser eficaz en el pleno conocimiento de todo bien. Hebreos 4:12 declara que la palabra de Dios es viva y eficaz, penetrando hasta la división del alma y del espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67214, 'spa', 'Rencor y hostilidad', 'Marcos 6:19 relata que Herodías guardaba rencor contra Juan el Bautista y quería matarlo por condenar su matrimonio. Lucas 11:53 describe cómo los escribas y fariseos comenzaron a acosarlo con preguntas hostiles. Gálatas 5:1 advierte contra someterse nuevamente al yugo de esclavitud, usando la imagen de quedar atrapado en una obligación opresora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67215, 'spa', 'Aquí, en este lugar — adverbio de lugar que significa ''aquí, en este lugar'', ind', 'Aquí, en este lugar — adverbio de lugar que significa ''aquí, en este lugar'', indicando proximidad a la ubicación actual del hablante. Usado por el Jesús resucitado al pedir alimento para demostrar su realidad corporal (Lc 24:41), por la mujer samaritana en el pozo de Jacob (Jn 4:15-16), por Pablo en la cárcel de Filipos (Hch 16:28), y en otros contextos narrativos que requieren deixis espacial (Hch 10:18; 17:6).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67217, 'spa', 'Reflexión deliberada', 'Ponderar o considerar mentalmente asuntos de peso que requieren deliberación. En Mt 1:20, José «considera» repudiar a María en secreto, una decisión que exige reflexión seria. En Mt 9:4, Jesús percibe lo que los escribas «piensan» (dudas hostiles sobre su autoridad para perdonar). En Hch 10:19, Pedro «reflexiona» sobre la visión recién recibida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67218, 'spa', 'Pensamiento interior', 'Pensamientos, reflexiones o deliberaciones internas, especialmente aquellas ocultas a los demás pero transparentes ante Dios. La raíz ἐν-θυμ- (''dentro del espíritu'') apunta a su carácter interior. En Mateo 9:4 y 12:25, Jesús percibe sobrenaturalmente las ἐνθυμήσεις hostiles de los adversarios religiosos. Hechos 17:29 lo extiende a las concepciones artísticas humanas. Hebreos 4:12 lo empareja con ἐννοιῶν para abarcar toda la actividad mental interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67219, 'spa', 'Haber, existir', 'Forma existencial enfática que significa ''hay'' o ''existe'', usada para afirmar o negar la presencia o existencia de algo dentro de un ámbito determinado. En su empleo más célebre, Pablo usa la forma contraída ἔνι tres veces en Gálatas 3:28 para declarar que las distinciones humanas fundamentales ya no existen ''en Cristo Jesús''. La misma construcción reaparece en Colosenses 3:11 y 1 Corintios 6:5.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67220, 'spa', 'año — Período de aproximadamente doce meses, usado para medir el tiempo calendár', 'año — Período de aproximadamente doce meses, usado para medir el tiempo calendárico, los ciclos litúrgicos y la duración de actividades. En Hebreos denota el ritmo anual del Día de la Expiación — el sumo sacerdote entrando ''una vez al año'' (Heb 9:7, 10:1, 10:3) — donde la repetición resalta el contraste con la ofrenda singular e irrepetible de Cristo. En los Evangelios, Caifás es identificado como sumo sacerdote ''aquel año'' (Jn 11:49, 51; 18:13), cargando la referencia temporal con profunda ironía narrativa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67223, 'spa', 'Estar presente', 'Estar presente, estar actualmente en vigor: se usa adjetivalmente con formas de participio perfecto para describir condiciones, períodos o realidades que están a la mano, en contraposición con lo pasado o futuro. Cinco de siete apariciones portan este sentido: las ''cosas presentes'' no pueden separarnos del amor de Dios (Ro 8:38), las ''cosas presentes'' os pertenecen en Cristo (1 Co 3:22), la ''angustia presente'' aconseja la soltería (1 Co 7:26).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67225, 'spa', 'Sobrevenir, ser inminente', 'Sobrevenir, llegar, ser inminente: describe eventos que se aproximan o que acaban de irrumpir, con fuerza dinámica más que estativa. Dos apariciones marcan este sentido: la advertencia de Pablo de que ''vendrán tiempos difíciles'' en los últimos días (2 Ti 3:1), usando el futuro ἐνστήσονται, y la alarma de los tesalonicenses de que ''el día del Señor ha llegado'' (2 Ts 2:2), usando el perfecto ἐνέστηκεν con matiz ingresivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67229, 'spa', 'Numeral ordinal ''noveno'', usado en el NT exclusivamente para senalar la hora nov', 'Numeral ordinal ''noveno'', usado en el NT exclusivamente para senalar la hora novena, aproximadamente las 3 PM segun la division judia del dia. Enmarca el momento culminante de la crucifixion cuando la oscuridad se disipa y Jesus clama desde la cruz (Mt 27:45-46; Mr 15:33-34; Lc 23:44). En la parabola de los obreros de la vina, los trabajadores contratados a la hora novena son de los ultimos (Mt 20:5). Cornelio recibe su vision y ora a esta misma hora (Hch 10:3, 30).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67230, 'spa', 'Número cardinal nueve', 'El número cardinal nueve, empleado para contar y agrupar. Las cinco apariciones neotestamentarias corresponden a palabras de Jesús: las noventa y nueve ovejas dejadas en los montes (Mt 18:12-13; Lc 15:4, 7) y los nueve leprosos sanados que no regresaron a dar gracias (Lc 17:17). Las traducciones lo vierten uniformemente como simple numeral, confirmando un sentido único.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67231, 'spa', 'Número noventa', 'El número cardinal noventa, usado en el Nuevo Testamento únicamente dentro del compuesto ''noventa y nueve'' en la parábola de la oveja perdida. Las cuatro apariciones (Mateo 18:12-13; Lucas 15:4, 7) presentan a las noventa y nueve como el rebaño que queda resguardado mientras el pastor va en busca de la única oveja extraviada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67232, 'spa', 'Mudo por asombro', 'Hechos 9:7 describe a los compañeros de Pablo como ἐνεοί —mudos de asombro— tras la voz celestial dirigida a Saulo. Es un silencio de sobrecogimiento ante el misterio divino. El adjetivo en plural captura la conmoción colectiva: oyen sonido pero no comprenden nada, quedando mudos y atónitos. Este enmudecimiento revela la magnitud sobrecogedora de la revelación divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67233, 'spa', 'Hacer señas', 'Lucas 1:62 muestra a la gente haciendo señas (ἐνένευον) para preguntar al mudo Zacarías qué nombre dar al niño. Es comunicación gestual forzada por su mudez. El tiempo imperfecto sugiere intentos repetidos o continuos de señalización. Este recurso comunicativo resalta la gravedad del silencio divino impuesto a Zacarías como señal del poder de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67236, 'spa', 'De noche, de madrugada', 'Marcos 1:35 describe a Jesús levantándose ἔννυχα λίαν —muy temprano, todavía de noche— para orar a solas. Esta precisión temporal subraya la intencionalidad de Jesús: ora en la oscuridad antes de que amanezca. En el uso clásico incluía actividades nocturnas. Marcos muestra la prioridad de Jesús: antes de sanar y enseñar, primero debe estar con el Padre.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67237, 'spa', 'Morar interiormente', 'Habitar dentro de, morar espiritualmente. Cada uso neotestamentario es metafórico: el Espíritu inhabita al creyente (Ro 8:11), Dios mora entre su pueblo (2 Co 6:16), la palabra de Cristo hace su hogar en la congregación (Col 3:16), y la fe genuina reside en el linaje de Timoteo (2 Ti 1:5, 14). El prefijo ἐν- más οἰκέω subraya residencia interior.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67240, 'spa', 'Culpable, reo, merecedor de (culpabilidad legal/moral)', 'Culpable, reo, merecedor de (culpabilidad legal/moral). Adjetivo de culpabilidad juridica y moral: culpable, reo, merecedor de una pena. Domina el uso neotestamentario (9 de 10 apariciones), especialmente en la ensenanza de Jesus sobre la gravedad creciente de las ofensas en Mateo 5:21-22, donde tres usos sucesivos intensifican desde ''reo ante el tribunal'' pasando por ''culpable ante el concilio'' hasta ''merecedor del fuego de la Gehena''. El veredicto del Sanedrin en el juicio de Jesus (Mt 26:66; Mr 14:64) emplea este mismo termino con fuerza condenatoria.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67243, 'spa', 'Sujeto a, sometido a servidumbre', 'Sujeto a, sometido a servidumbre. Adjetivo que indica sujecion, esclavitud o cautiverio bajo una condicion o poder, distinto de la culpa juridica. Aparece unicamente en Hebreos 2:15, donde describe a quienes por temor a la muerte estaban ''sujetos'' a esclavitud perpetua. La traduccion espanola ''sujetos'' en lugar de ''culpables'' marca claramente el cambio semantico: se trata de estar atado bajo una condicion tiranica, no de responsabilidad penal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67244, 'spa', 'Preceptos humanos', 'Mateo 15:9 y Marcos 7:7 citan Isaías 29:13 en la crítica de Jesús a los fariseos: «en vano me honran, enseñando como doctrinas mandamientos de hombres», tradiciones humanas que desplazan la Torá divina. Colosenses 2:22 advierte contra regulaciones ascéticas «según preceptos y enseñanzas de hombres», normas inventadas sobre alimentos y conducta.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67247, 'spa', 'mandar, dar órdenes — Emitir un mandato o directiva autoritativa que espera cump', 'mandar, dar órdenes — Emitir un mandato o directiva autoritativa que espera cumplimiento. Se usa para mandatos divinos (Mt 4:6, Dios mandando a sus ángeles; Hch 13:47, la comisión del Señor), para instrucciones de Jesús a sus seguidores (Mt 17:9; 28:20) y para prescripciones legales mosaicas citadas en disputas (Mt 19:7; Mc 10:3). La voz media (ἐντέλλομαι) enfatiza la autoridad personal en la emisión de la orden.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67253, 'spa', 'De aqui, desde este lugar', 'De aqui, desde este lugar. Sentido espacial basico: ''de aqui'', ''desde este lugar'', indicando movimiento de alejamiento respecto a la ubicacion del hablante o del relato. Aparece ocho veces en los Evangelios y Hechos: Jesus ordena partir de un lugar (Lc 4:9; Jn 14:31), manda retirar las mercancias del templo (Jn 2:16), y los fariseos advierten a Jesus que se vaya ''de aqui'' (Lc 13:31).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67254, 'spa', 'De un lado, de este lado', 'De un lado, de este lado. Uso espacial distributivo que significa ''de un lado'' (emparejado con ''del otro lado''), senalando la posicion a ambos flancos de un punto central. Ambas apariciones estan en Juan 19:18, describiendo a los dos criminales crucificados a cada lado de Jesus. La expresion espanola ''de un lado... del otro lado'' refleja la fuerza posicional y simetrica que distingue este sentido de la mera partida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67257, 'spa', 'Honrado y estimado', 'Honrado, estimado, tenido en alta consideración entre las personas. Se aplica al siervo del centurión que le era querido (Lucas 7:2), al puesto más honroso en un banquete (Lucas 14:8) y a líderes como Epafrodito a quienes los creyentes deben tener en gran estima (Filipenses 2:29). Refleja un valor reconocido socialmente dentro de una comunidad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67258, 'spa', 'mandamiento, precepto', 'Directiva autoritativa o precepto, referido principalmente a los mandatos divinos: el Decálogo (Mt 19:17-19), el ''gran mandamiento'' (Mt 22:36-38), el ''mandamiento nuevo'' de Jesús de amarse unos a otros (Jn 13:34; 15:12) y el llamado apostólico a guardar los mandamientos de Dios (1 Jn 2:3-4). Se distingue de νόμος (la ley como sistema) por su enfoque en el precepto individual y concreto.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67264, 'spa', 'Residente local', 'Hechos 21:12 registra que «tanto nosotros como los de aquel lugar» (οἱ ἐντόπιοι) rogaron a Pablo que no subiera a Jerusalén. El adjetivo señala a los residentes locales en distinción de los compañeros de viaje. El uso clásico oponía a los ἐντόπιοι frente a los extranjeros. Lucas muestra un consenso amplio: todos, ya fueran visitantes o lugareños, suplicaban a Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67267, 'spa', 'Respetar, reverenciar', 'Mostrar respeto, reverencia o deferencia hacia una persona, especialmente una figura de autoridad. Se usa predominantemente en la parábola de los labradores malvados, donde el dueño envía a su hijo esperando que ''lo respeten'' (Mt 21:37; Mc 12:6; Lc 20:13). También aparece para el juez injusto que ''ni respetaba a los hombres'' (Lc 18:2, 4).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67268, 'spa', 'Avergonzar, causar vergüenza', 'Causar vergüenza, hacer que alguien se sienta avergonzado, o amonestar provocando un sentimiento de bochorno moral. Pablo lo emplea pastoralmente en 1 Corintios 4:14: ''No escribo esto para avergonzaros, sino para amonestaros como a hijos amados.'' En 2 Tesalonicenses 3:14 y Tito 2:8 el propósito es correctivo: producir una vergüenza saludable que conduzca al arrepentimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67275, 'spa', 'Nutrirse en doctrina', 'En 1 Timoteo 4:6, Pablo elogia a Timoteo como quien «se nutre» (ἐντρεφόμενος) en las palabras de la fe y la sana enseñanza. El participio presente indica formación continua, no aprendizaje puntual. Es lenguaje alimentario aplicado a la doctrina: Timoteo se alimenta continuamente de la verdad. El uso clásico de criarse o formarse en algo encaja perfectamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67276, 'spa', 'Temblor reverencial', 'Temblar físicamente por temor, particularmente temor reverencial ante la presencia divina. En Hechos 7:32, Moisés queda «temblando» y no puede mirar la zarza ardiente. En Hechos 16:29, el carcelero se acerca «temblando» tras presenciar el terremoto. En Hebreos 12:21, Moisés declara «estoy temblando» ante el terror del Sinaí.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67278, 'spa', 'Deleitarse con exceso', 'Segunda Pedro 2:13 condena a quienes «se deleitan en sus engaños» (ἐντρυφῶντες ἐν ταῖς ἀπάταις) mientras comparten mesa con los creyentes. El participio presente retrata autocomplacencia continua y desvergonzada. Estos falsos maestros se recrean en su propio fraude durante comidas de comunión. El uso clásico abarcaba desde el goce legítimo hasta la burla despectiva.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67279, 'spa', 'Interceder o apelar', 'Interceder o apelar ante una persona con autoridad en favor de otro o en su contra. El Espíritu intercede por los creyentes según la voluntad de Dios (Romanos 8:27), Cristo intercede a la diestra de Dios (Romanos 8:34, Hebreos 7:25). Negativamente, la multitud judía peticionó a Festo contra Pablo (Hechos 25:24).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67280, 'spa', 'Envolver para sepultar', 'Mateo 27:59 relata la acción de José de Arimatea: «José tomó el cuerpo y lo envolvió en una sábana limpia», preparándolo para la sepultura. Lucas 23:53 describe igualmente: «lo bajó y lo envolvió en una sábana y lo puso en un sepulcro». Juan 20:7 describe el hallazgo de la resurrección: el sudario que había estado sobre la cabeza de Jesús, enrollado aparte.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67281, 'spa', 'Grabar en piedra', 'En 2 Corintios 3:7, Pablo se refiere al ministerio de muerte «grabado en piedras» (ἐντετυπωμένη ἐν λίθοις). Es vocabulario del Sinaí: los Diez Mandamientos tallados en tablas de piedra. El participio perfecto pasivo subraya la permanencia: una vez grabado, queda fijo. El contraste paulino es llamativo: el grabado externo traía muerte, pero la inscripción del Espíritu da vida.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67282, 'spa', 'Ultrajar lo sagrado', 'Hebreos 10:29 advierte del castigo para quien «ultraje al Espíritu de gracia» (τὸ πνεῦμα... ἐνυβρίσας). El participio aoristo marca acción completada: desprecio voluntario y arrogante hacia la obra del Espíritu Santo. Es lenguaje de apostasía: tratar la sangre de Cristo como cosa común y escarnecer al Espíritu. El uso clásico incluía burla y escarnio hacia personas.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67284, 'spa', 'Sueño revelador', 'Hechos 2:17 cita la profecía de Joel sobre ancianos que soñarán ἐνυπνίοις —sueños— emparejados con las visiones de los jóvenes, abarcando todos los modos de revelación divina. El dativo plural indica que los sueños son el medio de comunicación. Pedro interpreta Pentecostés como cumplimiento: el Espíritu derramado abre los canales de revelación sobrenatural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67285, 'spa', 'delante de, en presencia de', 'Preposición impropia (con genitivo) que significa ''delante de, en presencia de, a los ojos de'', transmitiendo el sentido de estar bajo la observación directa o la autoridad de alguien. Su mayor concentración se halla en Lucas-Hechos y Apocalipsis, donde sitúa repetidamente la acción humana ante la mirada divina: caminar intachablemente ''delante de Dios'' (Lc 1:6, 75), hablar con denuedo ''ante'' los gobernantes (Hch 4:19) y las escenas de adoración ante el trono celestial (Ap 4:5; 7:9).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67287, 'spa', 'Nombre propio patriarcal', 'Lucas 3:38 incluye a Ἐνὼς en la genealogía de Jesús como hijo de Set, hijo de Adán, hijo de Dios, trazando el linaje hasta los orígenes de la humanidad. Génesis 4:26 asocia a Enós con el inicio de la adoración: «Los hombres comenzaron a invocar el nombre del Señor». La regresión genealógica de Lucas establece a Jesús como nuevo Adán.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67288, 'spa', 'Escuchar atentamente', 'Hechos 2:14 registra la apertura del sermón de Pedro: «Escuchad mis palabras» (ἐνωτίσασθε τὰ ῥήματά μου). El imperativo aoristo en voz media exige una escucha personal y deliberada. Es más que «oír»: implica «prestar atención». El uso en la LXX transmitía la idea de obedecer la voz de Dios. Pedro requiere la completa atención de la multitud.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67289, 'spa', 'Patriarca Enoc', 'Nombre propio del patriarca Enoc, hijo de Jared, padre de Matusalén (Gn 5:18-24). En Lucas 3:37 aparece en la genealogía de Jesús. En Hebreos 11:5 ejemplifica la vida de fe que agradó a Dios, resultando en ser «trasladado» sin morir. En Judas 1:14 se le identifica como profeta que predijo el juicio divino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67290, 'spa', 'seis — El número cardinal seis, usado para contar días, meses, objetos y otras c', 'seis — El número cardinal seis, usado para contar días, meses, objetos y otras cantidades. Marca intervalos temporales como los seis días antes de la Transfiguración (Mt 17:1, Mc 9:2), los seis meses del embarazo de Elisabet (Lc 1:26, 36) y la hora sexta del día (Jn 4:6). También cuenta objetos concretos como las seis tinajas de agua en Caná (Jn 2:6). Las 13 apariciones expresan un uso numérico directo y sin carga simbólica especial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67293, 'spa', 'Redimir o rescatar', 'Comprar de vuelta o rescatar de la esclavitud, especialmente de la maldición de la Ley. El uso paulino en Gálatas 3:13 (''Cristo nos redimió'') y 4:5 (''para redimir a los que estaban bajo la Ley'') recurre a la imagen del mercado: adquirir la libertad de un esclavo. Las formas de aoristo y subjuntivo subrayan el carácter decisivo y consumado de esta transacción liberadora.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67294, 'spa', 'sacar, conducir afuera — Conducir o sacar a alguien de un lugar, típicamente de ', 'sacar, conducir afuera — Conducir o sacar a alguien de un lugar, típicamente de un encierro, cautiverio o espacio cerrado hacia la libertad o territorio abierto. Abarca la liberación divina (Hch 7:36, Dios sacando a Israel de Egipto; Hch 5:19, un ángel liberando a los apóstoles de la cárcel), la escolta militar (Mc 15:20, los soldados sacando a Jesús para la crucifixión) y la guía pastoral (Jn 10:3, el pastor sacando a sus ovejas).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67302, 'spa', 'Arrancar, sacar', 'Arrancar, sacar o remover a la fuerza una parte del cuerpo — el sentido literal en voz activa de extracción física. Se usa exclusivamente en la enseñanza hiperbólica de Jesús sobre la autodisciplina radical: ''Si tu ojo derecho te hace pecar, sácatelo y tíralo'' (Mt 5:29; cf. Mt 18:9). La violencia física lo distingue claramente del sentido de rescate.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67303, 'spa', 'Rescatar, librar', 'Rescatar, librar o poner en libertad ante un peligro, opresión o enemigos — el sentido soteriológico en voz media. Dios es el agente principal: rescata a José de sus aflicciones (Hch 7:10), desciende para librar a Israel de la esclavitud (Hch 7:34), envía un ángel para liberar a Pedro de prisión (Hch 12:11) y promete librar a Pablo (Hch 26:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67308, 'spa', 'Expulsar o remover', 'En 1 Corintios 5:13, Pablo ordena: «Quitad al malvado de entre vosotros» (ἐξάρατε τὸν πονηρόν). Es vocabulario de disciplina eclesiástica tomado de las fórmulas de purga de Deuteronomio. El imperativo aoristo exige acción inmediata: expulsar al pecador impenitente. Pablo insiste en la pureza comunitaria mediante la remoción del mal.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67309, 'spa', 'Demandar con autoridad', 'Lucas 22:31 contiene la advertencia de Jesús: «Satanás os ha pedido» (ἐξῃτήσατο ὑμᾶς). La voz media en aoristo sugiere la demanda personal y agresiva de Satanás para probar a los discípulos. Esto evoca Job 1-2, donde Satanás solicita permiso para afligir al justo. El uso clásico de exigir la entrega de criminales añade peso ominoso al pasaje.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67310, 'spa', 'De repente', 'De repente, de golpe, sin aviso previo. Se emplea para señalar momentos dramáticos de intervención divina o sobrenatural: la multitud angélica apareciendo ante los pastores (Lucas 2:13), un espíritu apoderándose repentinamente de un niño (Lucas 9:39), una gran luz del cielo resplandeciendo alrededor de Saulo (Hechos 9:3; 22:6) y el retorno escatológico del señor (Marcos 13:36).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67311, 'spa', 'Seguir con compromiso', 'En 2 Pedro 1:16, los apóstoles defienden que no siguieron «fábulas ingeniosas», sino que fueron testigos oculares del poder de Cristo. En 2 Pedro 2:2, muchos seguirán la sensualidad de falsos maestros, blasfemando el camino de la verdad. El verbo implica una adhesión deliberada y persistente, ya sea a la verdad apostólica o al error destructivo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67313, 'spa', 'Borrar o cancelar', 'Borrar, cancelar o anular un registro escrito, particularmente de pecado u obligación legal. Pedro llama al arrepentimiento para que los pecados sean borrados (Hechos 3:19), y Pablo declara que Cristo anuló el acta de decretos contra nosotros (Colosenses 2:14). En Apocalipsis 3:5 la imagen se invierte: borrar un nombre del libro de la vida como juicio.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67314, 'spa', 'Saltar con gozo', 'Hechos 3:8 describe vívidamente la reacción del cojo ante su sanidad: «saltando, se puso en pie y anduvo». El participio aoristo ἐξαλλόμενος capta el movimiento explosivo ascendente desde la postración hasta ponerse de pie. No se trata de un tanteo cauteloso, sino de un brinco exuberante. El uso clásico para saltar fuera o brincar encaja perfectamente. Lucas resalta la plenitud instantánea de la restauración divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67315, 'spa', 'Resurrección escatológica', 'Filipenses 3:11 articula la meta suprema de Pablo: «si en alguna manera llegase a la resurrección de entre los muertos» (τὴν ἐξανάστασιν τὴν ἐκ νεκρῶν). El doble artículo enfatiza esta resurrección particular. Pablo subordina todos sus logros a esta única esperanza: compartir la resurrección de Cristo. El uso clásico incluía levantarse de la cama, pero el uso neotestamentario es plenamente escatológico. Su «si en alguna manera» expresa anhelo reverente, no duda.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67317, 'spa', 'Suscitar descendencia', 'Levantar o hacer surgir, especialmente descendencia para un hermano fallecido según la costumbre del levirato. En Marcos 12:19 y Lucas 20:28, los saduceos citan la ley que requiere que un hermano «suscite descendencia» para la viuda de su hermano difunto. En Hechos 15:5, fariseos creyentes «se levantaron» para exponer su posición, donde el sentido se desplaza hacia ponerse de pie para hablar.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67318, 'spa', 'Engañar completamente', 'Engañar por completo, seducir totalmente, extraviar de manera absoluta. El prefijo ἐξ- intensifica el verbo base ἀπατάω, indicando un engaño integral y no superficial. En Ro 7:11, el pecado ''engañó por completo'' a Pablo mediante el mandamiento; en 2 Co 11:3, la serpiente ''sedujo totalmente'' a Eva; en Ro 16:18, los falsos maestros engañan los corazones de los incautos; en 1 Co 3:18, Pablo advierte contra el autoengaño.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67322, 'spa', 'Repentinamente', 'Marcos 9:8 describe el final de la Transfiguración: ἐξάπινα —«de repente»— mirando alrededor, solo vieron a Jesús. El adverbio marca la transición abrupta de la gloria a la realidad ordinaria. Moisés y Elías desaparecen; el resplandor se desvanece; solo Jesús permanece. El uso clásico para relámpagos o sucesos imprevistos encaja con la visión de Marcos sobre la manifestación divina que aparece y se retira en un instante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67324, 'spa', 'enviar fuera, despachar (con autoridad o comisión) — Enviar o despachar a alguie', 'enviar fuera, despachar (con autoridad o comisión) — Enviar o despachar a alguien con propósito, autoridad o comisión divina — forma intensificada de ἀποστέλλω con el prefijo ἐξ- (''fuera de'') que enfatiza la partida y la misión. Usos teológicos clave incluyen a Dios enviando a su Hijo y al Espíritu (Gá 4:4, 6) y la comisión divina de los apóstoles (Hch 22:21). Usos narrativos incluyen el envío de siervos a una viña (Lc 20:10-11) y el despacho de emisarios (Hch 11:22).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67331, 'spa', 'Resplandor deslumbrante', 'Lucas 9:29 describe la vestidura de Jesús en la Transfiguración como ἐξαστράπτων —«resplandeciente» o «fulgurante de blancura». El participio presente sugiere un brillo radiante continuo. Se trata del lenguaje de gloria teofánica: las vestiduras de Jesús brillan con fulgor de relámpago. El uso clásico para la luz del sol o el destello del rayo encaja con la visión de Lucas de la gloria divina irrumpiendo en el mundo visible.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67332, 'spa', 'Inmediatamente, al instante', 'Adverbio temporal que significa ''inmediatamente, enseguida, al instante'', indicando que una acción sigue a otra sin demora alguna. Etimológicamente proviene de ἐξ αὐτῆς (ὥρας) — ''desde esa misma (hora)''. En Marcos 6:25 describe la alarmante rapidez con que la hija de Herodías regresa pidiendo la cabeza de Juan. En Hechos, Lucas lo usa repetidamente para impulsar el ritmo narrativo: el envío inmediato de Cornelio, la llegada pronta desde Cesarea y el despacho nocturno de Pablo.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67335, 'spa', 'Salir o partir', 'Salir o partir de un lugar específico, implicando una salida deliberada y con propósito. Las cuatro apariciones neotestamentarias se hallan en Hechos dentro de narrativas de viaje: salir de una sinagoga (13:42), emprender un recorrido (17:15), prepararse para partir al día siguiente (20:7) y escapar a tierra firme (27:43). Las formas participiales refuerzan el sentido de movimiento intencional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67336, 'spa', 'Ser arrastrado por deseo', 'Santiago 1:14 describe el mecanismo de la tentación: cada uno es «arrastrado» (ἐξελκόμενος) por su propio deseo y seducido. El participio pasivo presente sugiere una vulnerabilidad continua a ser desviado del camino. Se trata de imágenes de pesca y caza: el deseo pone el cebo en el anzuelo y luego arrastra a la víctima. El uso clásico para arrastrar heridos o sacar de la esclavitud refuerza la imagen de una fuerza irresistible que actúa sobre la voluntad debilitada.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67337, 'spa', 'Vómito, materia expulsada', 'En 2 Pedro 2:22 se cita Proverbios 26:11: «el perro vuelve a su propio vómito» (ἐξέραμα). Esta imagen deliberadamente repulsiva representa la apostasía: quienes conocen a Cristo pero regresan al pecado son como perros que comen sus propias inmundicias. Pedro comunica un mensaje visceral: abandonar a Cristo tras haberle conocido es moral y espiritualmente degradante.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67338, 'spa', 'Escudriñar con diligencia', 'En 1 Pedro 1:10, los profetas «escudriñaron e inquirieron diligentemente» (ἐξηραύνησαν) sobre la salvación que predijeron. El aoristo marca una investigación completada. Estos profetas fueron tanto proclamadores como investigadores perplejos, examinando sus propias palabras inspiradas por el Espíritu para comprender el cumplimiento y los tiempos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67339, 'spa', 'salir físicamente', 'Movimiento físico de dentro hacia fuera, el sentido dominante con 193 apariciones. Abarca toda instancia concreta de salir, partir o abandonar un lugar: Jesús ''salió'' de la casa (Mt 13:1), toda la ciudad ''salió'' a su encuentro (Mt 8:34), el sembrador ''salió'' a sembrar (Mt 13:3), y los espíritus inmundos ''salieron'' de los endemoniados (Mt 17:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67347, 'spa', 'difundirse o emanar', 'Extensión figurada: lo que ''sale'' no es una persona sino una noticia, una palabra o un fenómeno. La fama ''se difundió'' por toda aquella tierra (Mt 9:26), las cosas malas ''salen del corazón'' (Mt 15:18-19), y el relámpago ''sale'' del oriente (Mt 24:27). Con 10 apariciones, este sentido muestra cómo la imagen espacial de salida se traslada naturalmente a la propagación.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67349, 'spa', 'salir como mandato', 'Mandatos imperativos de salir, 13 apariciones donde el verbo porta fuerza de directiva autoritativa. Destaca en los exorcismos: ''¡Sal de él, espíritu inmundo!'' (Mc 5:8; cf. Mc 1:25, 9:25, Lc 4:35). También en el clamor de medianoche ''¡Salid al encuentro del esposo!'' (Mt 25:6) y la orden paulina de separarse de los incrédulos (2 Co 6:17).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67354, 'spa', 'apartarse o retirarse', 'Partida deliberada o distanciamiento relacional, 3 apariciones donde el énfasis recae en la separación personal más que en la salida espacial. Pedro dice ''Apártate de mí, Señor, que soy hombre pecador'' (Lc 5:8); los creyentes de Cesarea acompañan a Pablo al ''partir'' (Hch 21:5, 21:8). El matiz relacional distingue este sentido de la simple salida física.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67378, 'spa', 'es lícito, está permitido', 'es lícito, está permitido');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67385, 'spa', 'Indagar con esmero', 'Examinar detenidamente o inquirir con cuidado, a menudo en contextos que requieren discernimiento o investigación. La raíz griega sugiere un escrutinio minucioso: revisar, sopesar las palabras con exactitud, hacer averiguaciones entre quienes saben. En el relato de la natividad de Mateo, el mandato de Herodes a los magos emplea este vocablo con toda su fuerza investigativa, reflejando su uso en el ámbito legal y judicial.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67386, 'spa', 'Relatar, explicar, dar a conocer', 'Relatar, narrar, explicar o dar a conocer en detalle: ofrecer un recuento completo de hechos, experiencias o verdades. De este verbo deriva el término ''exégesis''. Su punto culminante teológico es Juan 1:18, donde se dice que el Hijo ''dio a conocer'' (ἐξηγήσατο) al Dios invisible, un acto de narración divina que revela el carácter del Padre. En Lucas 24:35 los discípulos de Emaús ''explican'' lo acontecido en el camino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67392, 'spa', 'Sesenta', 'El número cardinal sesenta, usado en el Nuevo Testamento para cantidades, medidas y rendimientos proporcionales. Aparece destacadamente en la parábola del sembrador, donde el sesenta por uno representa el nivel intermedio de fecundidad entre treinta y cien (Mt 13:8, 13:23; Mc 4:8, 4:20). También marca la distancia a Emaús como sesenta estadios (Lc 24:13).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67393, 'spa', 'Al día siguiente', 'Siguiente en secuencia temporal, al día u ocasión posterior. Las cinco apariciones neotestamentarias sirven como marcadores narrativos: Jesús fue a Naín al día siguiente (Lucas 7:11), tras la Transfiguración (Lucas 9:37), al partir de Mileto (Hechos 21:1), tras la llegada de los acusadores (Hechos 25:17) y durante la tempestad (Hechos 27:18).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67394, 'spa', 'Resonar, hacer eco', 'En 1 Tesalonicenses 1:8, Pablo elogia a la iglesia: «de vosotros ha resonado la palabra del Señor» (ἐξήχηται). El tiempo perfecto indica reverberación continua: el evangelio sigue resonando desde Tesalónica. El uso clásico para hacer resonar cantos encaja con la imagen paulina del evangelio retumbando como trompeta. Los tesalonicenses se convirtieron en amplificadores vivientes de la fe.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67395, 'spa', 'Hábito, práctica arraigada', 'En Hebreos 5:14, los creyentes maduros «por la práctica» (διὰ τὴν ἕξιν) han ejercitado sus sentidos para distinguir el bien del mal. El sustantivo denota un hábito consolidado mediante la repetición, no conocimiento teórico sino destreza practicada. El uso clásico distinguía la ἕξις permanente de la σχέσις temporal. La madurez espiritual se forja mediante el ejercicio constante del discernimiento.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67396, 'spa', 'Estar lleno de asombro o estupefaccion ante algo presenciado u oido', 'Estar lleno de asombro o estupefaccion ante algo presenciado u oido. Es el sentido dominante del NT, apareciendo en los Evangelios Sinopticos y Hechos. Mc 2:12 registra el asombro de la multitud tras la sanidad de un paralitico, y Lc 2:47 describe a los maestros asombrados ante el joven Jesus. Captura la reaccion involuntaria e incontrolable de quedar fuera de si por la maravilla.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67400, 'spa', 'Asombrar o dejar atonito a alguien, producir estupefaccion en otros', 'Asombrar o dejar atonito a alguien, producir estupefaccion en otros. Uso transitivo activo o causativo. Hch 8:9-11 lo emplea para Simon el mago que asombraba a los samaritanos con su hechiceria, y Lc 24:22 informa de las mujeres del sepulcro que dejaron atonitos a los discipulos. Preserva la direccion causativa: el sujeto produce asombro en otro.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67401, 'spa', 'Estar fuera de si, haber perdido el juicio, reflejando el significado literal de', 'Estar fuera de si, haber perdido el juicio, reflejando el significado literal de la raiz de desplazamiento del estado mental normal. En Mc 3:21 la familia de Jesus viene a prenderlo diciendo ''esta fuera de si'', y en 2 Co 5:13 Pablo escribe ''si estamos fuera de nosotros, es para Dios''. Este sentido revela la conexion etimologica de la palabra con la dislocacion mental.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67408, 'spa', 'Ser plenamente capaz', 'En Efesios 3:18, Pablo ora para que los creyentes «sean plenamente capaces» (ἐξισχύσητε) de captar las dimensiones del amor de Cristo junto con todos los santos. El aoristo de subjuntivo expresa propósito: Pablo pide poder habilitador para comprender lo incomprensible. Entender el amor de Cristo requiere una capacidad que trasciende lo humano y proviene del Espíritu.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67409, 'spa', 'Partida o éxodo', 'Todas las lenguas testimonian de manera consistente el sentido de «partida», «éxodo» o «salida», reflejando su raíz de movimiento hacia fuera de un lugar. Lucas 9:31 es especialmente conmovedor: la muerte de Jesús se enmarca como un «éxodo» que habría de cumplirse en Jerusalén, conectando su sacrificio con la liberación de Israel de Egipto y elevando el concepto de partida a un plano redentor.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67410, 'spa', 'Destrucción total divina', 'Hechos 3:23 advierte que todo aquel que rehúse escuchar al profeta «será completamente destruido» (ἐξολεθρευθήσεται) de entre el pueblo. El futuro pasivo subraya un juicio cierto ejecutado por Dios. Es lenguaje de maldición pactual del Deuteronomio aplicado a Cristo. El verbo intensifica la destrucción: no solo castigo, sino aniquilación absoluta y exclusión del pueblo de Dios.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67411, 'spa', 'Confesar (pecados o faltas)', 'Confesar (pecados o faltas). Confesar o reconocer abiertamente los pecados, transgresiones o faltas propias ante Dios o ante otros. Este sentido penitencial domina en el NT: aparece en el bautismo de Juan (Mt 3:6; Mr 1:5), en los conversos efesios que quemaban sus libros de magia (Hch 19:18), y en la cita de Pablo de Is 45:23 en Ro 14:11. El termino espanol ''confesando'' preserva el tono de reconocimiento publico y solemne.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67412, 'spa', 'Alabar, dar gracias (a Dios)', 'Alabar, dar gracias (a Dios). Alabar, dar gracias u ofrecer reconocimiento agradecido a Dios. Este sentido doxologico refleja el uso de ἐξομολογέομαι en la LXX para traducir el hebreo yadah (hifil), donde la confesion se tine de accion de gracias. En Mt 11:25 y Lc 10:21, Jesus exclama ''te alabo, Padre''; la expresion espanola ''te alabo'' senala inequivocamente adoracion y no penitencia.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67414, 'spa', 'Consentir, estar de acuerdo (con una propuesta)', 'Consentir, estar de acuerdo (con una propuesta). Consentir, aceptar o dar su conformidad a un plan o propuesta. Este sentido pragmatico aparece unicamente en Lucas 22:6, donde Judas ''consintio'' en el plan de los principales sacerdotes para traicionar a Jesus. El espanol ''consintio'' marca claramente que se trata de un acuerdo volitivo y no de una confesion religiosa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67418, 'spa', 'Conjurar bajo juramento', 'Mateo 26:63 registra la adjuración del sumo sacerdote: «Te conjuro por el Dios viviente» (Ἐξορκίζω σε κατὰ τοῦ θεοῦ τοῦ ζῶντος) para que declares si eres el Mesías. El indicativo presente marca un acto formal de juramento que impone la obligación más solemne de responder. En el uso clásico incluía el exorcismo, pero aquí es estrictamente jurídico.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67419, 'spa', 'Exorcistas profesionales', 'Hechos 19:13 identifica a «exorcistas judíos ambulantes» (ἐξορκιστῶν) que intentaron usar el nombre de Jesús como fórmula mágica. El genitivo plural los señala como expulsores profesionales de demonios. Estos practicantes invocaban diversos nombres, incluyendo «el Jesús que Pablo predica», para echar fuera espíritus. Pero los demonios reconocieron el uso no autorizado, y los exorcistas fueron vencidos violentamente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67421, 'spa', 'Desprecio y rechazo', 'Marcos 9:12 contiene la predicción de Jesús de que el Hijo del Hombre «será tratado con desprecio» (ἐξουδενωθῇ). El aoristo pasivo subjuntivo indica necesidad divina: el Mesías debe ser menospreciado. Esto combina la gloria del Hijo del Hombre de Daniel 7 con el rechazo del Siervo sufriente de Isaías 53. La gloria mesiánica viene mediante la humillación previa.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67422, 'spa', 'Despreciar, tratar con desprecio', 'Despreciar, tratar con desprecio. Tratar con absoluto desprecio, menospreciar como algo sin valor, o tener por nada: un rechazo activo del valor o la importancia de alguien. El fariseo desprecia a los demas (Lc 18:9), Herodes se burla de Jesus con desprecio (Lc 23:11), los edificadores rechazan la piedra angular (Hch 4:11) y los creyentes fuertes menosprecian a los debiles por cuestiones alimentarias (Ro 14:3, 10). Pablo advierte contra despreciar a un hermano a quien Dios ha aceptado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67432, 'spa', 'autoridad, poder', 'Autoridad o poder abstracto: la capacidad, el derecho o la libertad de actuar con fuerza legítima y control. Este sentido abrumadoramente dominante (91 de 102 apariciones) abarca desde la autoridad docente de Jesús (Mt 7:29), su potestad para perdonar pecados (Mt 9:6), la autoridad delegada a los discípulos (Mt 10:1), hasta la pretensión de autoridad judicial de Pilato (Jn 19:10).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67434, 'spa', 'autoridades, potestades', 'Las autoridades como entidades concretas: poderes gobernantes, gobernadores o principados sobrenaturales que ejercen dominio, generalmente en plural. Las ''autoridades constituidas'' ordenadas por Dios (Ro 13:1), los ''principados y potestades'' en los lugares celestiales (Ef 3:10; 6:12; Col 1:16), y las autoridades de la sinagoga ante las cuales los creyentes podrían ser arrastrados (Lc 12:11).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67439, 'spa', 'jurisdicción, dominio', 'Jurisdicción o dominio: el ámbito territorial o administrativo sobre el cual se extiende la autoridad. La única aparición en Lucas 23:7, donde Pilato descubre que Jesús pertenece a la jurisdicción (ἐξουσία) de Herodes y lo envía allí. El matiz espacial-jurídico distingue este sentido del poder abstracto del sentido 1.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67440, 'spa', 'derecho, privilegio', 'Derecho, privilegio o prerrogativa: la libertad o facultad de hacer algo, enfatizando el permiso y la pretensión legítima más que la fuerza o el control. En Hebreos 13:10, ''Tenemos un altar del cual no tienen derecho a comer los que sirven al tabernáculo.'' Esta única aparición destaca una faceta semántica donde ἐξουσία se traduce mejor como derecho que como autoridad.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67442, 'spa', 'Ejercer autoridad', 'Ejercer autoridad o dominio sobre otros, frecuentemente con connotaciones de control o señorío. Lucas 22:25 describe a gobernantes que ''ejercen autoridad'' sobre sus pueblos, mientras que Pablo en 1 Corintios 6:12 invierte el verbo en voz pasiva (''no seré dominado'') para afirmar su libertad frente a toda sujeción. El uso conyugal en 1 Corintios 7:4 aplica el término de manera recíproca entre esposos.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67443, 'spa', 'Pompa ceremonial', 'La evidencia multilingüe converge en dignidad ceremonial y exhibición pública. El término captura la elevación social y la distinción visible cuando Agripa y Berenice entran con gran pompa ante los oficiales reunidos. Se trata de prominencia como espectáculo público, no meramente una superioridad abstracta, sino una manifestación solemne de rango y autoridad ante la asamblea.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67444, 'spa', 'Despertar metafórico', 'Jesús emplea este verbo en sentido metafórico para referirse a la muerte y la resurrección. Las traducciones al español «despierte», al francés «réveiller» y al alemán «aufwecken» conservan el sentido básico de despertar, que Jesús redefine en la conversación con sus discípulos, quienes inicialmente malinterpretan pensando que Lázaro simplemente duerme de forma natural.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67445, 'spa', 'Despertar súbito', 'Las traducciones multilingües coinciden en representar un estado de vigilia repentina. El contexto dramático en Hechos muestra al carcelero despertado bruscamente por el terremoto, y su alarma inmediata contrasta con Pablo y Silas cantando himnos. No se trata de un despertar tranquilo sino de una vigilia de crisis que prepara el camino para la conversión del carcelero.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67446, 'spa', 'fuera, afuera (espacial)', 'Adverbio y preposición espacial que indica ubicación o movimiento fuera de un lugar, o que describe el exterior de algo. Abarca ser echado fuera (Mt 5:13), salir afuera de una casa (Mt 12:46) y usos atributivos como las ''tinieblas de afuera'' (Mt 8:12). El español distingue la dirección (''afuera'') de la ubicación estática (''fuera de''), confirmando este como el sentido primario y más frecuente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67447, 'spa', 'los de afuera (sustantivado)', 'Uso sustantivado que designa a personas que están fuera de un grupo, comunidad o círculo de fe: ''los de afuera''. Jesús lo emplea en Marcos 4:11 para distinguir a quienes reciben el misterio del reino de ''los que están fuera'', que solo oyen parábolas. Pablo adopta la misma convención para los no creyentes (1 Co 5:12-13; Col 4:5), pasando del sentido espacial al relacional.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67451, 'spa', 'Adverbio espacial que indica origen desde el exterior, la superficie externa o l', 'Adverbio espacial que indica origen desde el exterior, la superficie externa o la apariencia exterior en contraste con el interior. En los Evangelios sinópticos aparece en la enseñanza de Jesús sobre la pureza interior frente a la exterior: el exterior de la copa (Mt 23:25), el exterior del sepulcro (Mt 23:27) y lo que entra desde fuera del cuerpo (Mr 7:15, 18). Las lenguas traducen consistentemente con el sentido direccional ''desde afuera''.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67458, 'spa', 'Exterior o de afuera', 'Mateo emplea este término exclusivamente en la estremecedora frase «las tinieblas de afuera» (8:12, 22:13, 25:30), representando la separación espacial y relacional definitiva respecto al banquete de Dios. La raíz comparativa (de ἔξω, «fuera») intensifica el sentido de ser arrojado cada vez más lejos de la luz, el gozo y la comunión del reino.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67459, 'spa', 'Celebración festiva', 'El llamado de Pablo a «celebrar la fiesta» se apoya en la tradición pascual de eliminar la levadura. Las traducciones «celebremos» en español, «fête» en francés y «Fest-feiern» en alemán transmiten la idea de observancia festiva. Pablo reinterpreta la fiesta anual como un estado ético permanente: puesto que Cristo, nuestra Pascua, ha sido sacrificado, los creyentes deben celebrar perpetuamente con pureza moral.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67460, 'spa', 'Festividad religiosa o día santo, que en casi todas las ocurrencias neotestament', 'Festividad religiosa o día santo, que en casi todas las ocurrencias neotestamentarias se refiere a las fiestas de peregrinación judías, sobre todo la Pascua/Panes sin Levadura y Tabernáculos. En el Evangelio de Juan, la sucesión de fiestas proporciona el marco narrativo: la Pascua (Juan 2:23; 6:4; 11:55), Tabernáculos (Juan 7:2, 8, 10-14, 37) y una fiesta no especificada (Juan 5:1). Los Sinópticos concentran el término en la narrativa de la Pasión, señalando que las autoridades evitaban arrestar a Jesús ''durante la fiesta'' para no provocar un tumulto (Mateo 26:5; Marcos 14:2).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67462, 'spa', 'promesa, compromiso solemne', 'Compromiso solemne y divino, o promesa pactual. En las cartas paulinas, el vocablo ancla el argumento de que los propósitos salvíficos de Dios fluyen por la promesa a Abraham y no por la ley (Gá 3:14-18; Ro 4:13-16). En Hechos designa la promesa del Espíritu Santo cumplida en Pentecostés (Hch 1:4; 2:33). Hebreos celebra la fidelidad de quienes murieron sin recibir las promesas, pero las abrazaron desde lejos (Heb 11:13, 39).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67466, 'spa', 'El sentido dominante', 'El sentido dominante: prometer, especialmente referido a los compromisos solemnes y pactuales de Dios. Abarca la promesa de Dios a Abraham (Hch 7:5; Ro 4:21; He 6:13), la promesa de vida eterna (Tit 1:2; 1 Jn 2:25) y la promesa del Espíritu Santo (Gá 3:19). Mr 14:11 aplica la palabra a los conspiradores de Judas prometiéndole dinero — la única aparición no divina.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67469, 'spa', 'Sentido secundario', 'Sentido secundario: profesar, hacer una declaración pública o reclamar una cualidad. Se encuentra solo en las Epístolas Pastorales — mujeres que ''profesan piedad'' mediante buenas obras (1 Ti 2:10) y quienes al ''profesar'' conocimiento se han desviado de la fe (1 Ti 6:21). A diferencia del sentido 1, el enfoque no está en un compromiso futuro sino en una declaración pública presente.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67475, 'spa', 'Acarrear sobre', 'Las traducciones multilingües apuntan consistentemente a causación e introducción de algo adverso. Hechos 5:28 recoge el temor de las autoridades: «pretendéis hacer recaer sobre nosotros la sangre de ese hombre». En 2 Pedro, el término aparece dos veces: los falsos maestros «atraerán sobre sí mismos» destrucción repentina (2:1), y Dios «trajo» el diluvio sobre el mundo (2:5).');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67476, 'spa', 'Lucha ferviente', 'El uso singular de este verbo por parte de Judas transmite una urgencia militante. Las traducciones «contender» en español, «combattre» en francés y «kämpfen» en alemán enfatizan lucha y conflicto. No se trata de un debate casual sino de una guerra espiritual para preservar la integridad del evangelio frente a distorsiones heréticas. El prefijo intensivo ἐπι- refuerza el sentido de esfuerzo sostenido y enfocado.');
INSERT OR REPLACE INTO sense_entry_translation_chirho (sense_id_chirho, language_code_chirho, label_chirho, enriched_chirho) VALUES (67477, 'spa', 'Reunión multitudinaria', 'Lucas emplea este verbo vívido para ambientar la reprensión de Jesús a quienes buscan señales. Las traducciones «reuniéndose» en español y «s''assembler» en francés captan el movimiento de congregación, mientras el contexto sugiere una multitud creciente y apremiante. Jesús responde a esta asamblea cada vez mayor llamándolos «generación malvada» que busca señales cuando la única señal será la de Jonás.');